use core::cell::{RefCell, RefMut, UnsafeCell};
use core::ops::{Deref, DerefMut};
use lazy_static::*;
use riscv::register::sstatus;

/*
/// Wrap a static data structure inside it so that we are
/// able to access it without any `unsafe`.
///
/// We should only use it in uniprocessor.
///
/// In order to get mutable reference of inner data, call
/// `exclusive_access`.
pub struct UPSafeCell<T> {
    /// inner data
    inner: RefCell<T>,
}

unsafe impl<T> Sync for UPSafeCell<T> {}

impl<T> UPSafeCell<T> {
    /// User is responsible to guarantee that inner struct is only used in
    /// uniprocessor.
    pub unsafe fn new(value: T) -> Self {
        Self {
            inner: RefCell::new(value),
        }
    }
    /// Panic if the data has been borrowed.
    pub fn exclusive_access(&self) -> RefMut<'_, T> {
        self.inner.borrow_mut()
    }
}
*/

pub struct UPSafeCellRaw<T> {
    inner: UnsafeCell<T>,
}

unsafe impl<T> Sync for UPSafeCellRaw<T> {}

impl<T> UPSafeCellRaw<T> {
    pub unsafe fn new(value: T) -> Self {
        Self {
            inner: UnsafeCell::new(value),
        }
    }
    pub fn get_mut(&self) -> &mut T {
        unsafe { &mut (*self.inner.get()) }
    }
}

pub struct IntrMaskingInfo {
    nested_level: usize,
    sie_before_masking: bool,
}

lazy_static! {
    static ref INTR_MASKING_INFO: UPSafeCellRaw<IntrMaskingInfo> =
        unsafe { UPSafeCellRaw::new(IntrMaskingInfo::new()) };
}

impl IntrMaskingInfo {
    pub fn new() -> Self {
        Self {
            nested_level: 0,
            sie_before_masking: false,
        }
    }

    pub fn enter(&mut self) {
        let sie = sstatus::read().sie();
        unsafe {
            sstatus::clear_sie();
        }
        if self.nested_level == 0 {
            self.sie_before_masking = sie;
        }
        self.nested_level += 1;
    }

    pub fn exit(&mut self) {
        self.nested_level -= 1;
        if self.nested_level == 0 && self.sie_before_masking {
            unsafe {
                sstatus::set_sie();
            }
        }
    }
}

pub struct UPIntrFreeCell<T> {
    /// inner data
    inner: RefCell<T>,
}

unsafe impl<T> Sync for UPIntrFreeCell<T> {}

pub struct UPIntrRefMut<'a, T>(Option<RefMut<'a, T>>);

impl<T> UPIntrFreeCell<T> {
    pub unsafe fn new(value: T) -> Self {
        Self {
            inner: RefCell::new(value),
        }
    }

    /// Panic if the data has been borrowed.
    pub fn exclusive_access(&self) -> UPIntrRefMut<'_, T> {
        INTR_MASKING_INFO.get_mut().enter();
        UPIntrRefMut(Some(self.inner.borrow_mut()))
    }

    pub fn exclusive_session<F, V>(&self, f: F) -> V
    where
        F: FnOnce(&mut T) -> V,
    {
        let mut inner = self.exclusive_access();
        f(inner.deref_mut())
    }
}

impl<'a, T> Drop for UPIntrRefMut<'a, T> {
    fn drop(&mut self) {
        self.0 = None;
        INTR_MASKING_INFO.get_mut().exit();
    }
}

impl<'a, T> Deref for UPIntrRefMut<'a, T> {
    type Target = T;
    fn deref(&self) -> &Self::Target {
        self.0.as_ref().unwrap().deref()
    }
}
impl<'a, T> DerefMut for UPIntrRefMut<'a, T> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.0.as_mut().unwrap().deref_mut()
    }
}

## 一句话结论

教材版 `UPSafeCell` **没有“不可变借用”这个 API**——它只有一个方法 `exclusive_access(&self) -> RefMut<'_, T>`。想只读访问内部数据，只能借一个 `RefMut` 然后只读地用；想拿到真正的 `Ref`，得自己往 `impl` 里加。

## 全貌只有一个方法

```rust
// os/src/sync/up.rs  （ch3-coop 分支）
pub struct UPSafeCell<T> {
    inner: RefCell<T>,
}

unsafe impl<T> Sync for UPSafeCell<T> {}

impl<T> UPSafeCell<T> {
    pub unsafe fn new(value: T) -> Self {
        Self { inner: RefCell::new(value) }
    }
    /// Exclusive access inner data in UPSafeCell. Panic if the data has been borrowed.
    pub fn exclusive_access(&self) -> RefMut<'_, T> {
        self.inner.borrow_mut()
    }
}
```

它其实是一个**只保留 `borrow_mut` 的 `RefCell`**：

| `RefCell` | `UPSafeCell` |
|---|---|
| `borrow() -> Ref<T>` | ✗ 不存在 |
| `borrow_mut() -> RefMut<T>` | ✓ 改名 `exclusive_access()` |
| `!Sync`，不能进 `static` | `unsafe impl Sync`，可以进 `static` |

所以“不可变借用”这件事，运行时机制（`RefCell` 的借用标记）本来完全支持，被去掉的是 **API 层**。

## 于是「不可变借用」可以拆成三层

### ① 唯一真正的不可变借用：`&UPSafeCell<T>` 本身

`exclusive_access(&self)` 借的是 `&UPSafeCell`，内部可变性让你从 `&` 里摇出 `&mut T`。因为 `unsafe impl Sync`，你可以在任何地方、任何次数地拿 `&UPSafeCell`——这正是它存在的理由（放进 `static`、让 `lazy_static` 和全局访问函数共享）。但拿到之后，**读**也必须走 `exclusive_access` 这道闸门。

### ② 只读访问：借 `RefMut` 只读地用（推荐，零成本）

`RefMut<'_, T>` 同时实现了 `Deref<Target = T>` 和 `DerefMut`，所以只读用法不需要任何额外能力：

```rust
let inner = TASK_MANAGER.inner.exclusive_access(); // RefMut
let cur = inner.current_task;                       // 通过 Deref 只读
let n   = inner.num_app;
// 想更显式：
let r: &TaskManagerInner = &*inner;
```

注意语义差别：此时**运行时借用标记是“已可变借用”**，哪怕你一行都没改。任何并发的 `exclusive_access()` 都会 panic，不会给你“多个读者”的宽松度。

### ③ 真想要 `Ref<T>`：自己加，但要知道代价

```rust
use core::cell::Ref;

impl<T> UPSafeCell<T> {
    pub fn borrow(&self) -> Ref<'_, T> {
        self.inner.borrow()
    }
}
```

加上之后能用了，但有两个必须清楚的点：

- `Ref<'_, T>` 是 **`!Send`**（内部持有 `&Cell<BorrowFlag>`）。单核内核不跨线程，无所谓。
- 共享借用是**可叠加**的，这恰恰是危险所在：`Ref` 活得越久，越可能跨过一个“切换点”。

## 为什么教材故意不给

内核里的 `&T` 和用户态库里的 `&T` 不是一回事，因为它可能跨越：

- 一次 `__switch`（任务切换，栈整个换掉）；
- 一次 trap 进入/返回（中断在这个窗口里到来）；
- 第四章之后还多一个 **`satp` 切换**（地址空间换了，`&T` 指向的物理页可能已经不属于当前任务）。

一旦跨过去，“别人改了/释放了这块数据，我还拿着 `&T`”就从“借用检查器会拦住的错误”变成**UB**。而 `exclusive_access` 只允许存在一个 `RefMut`，任何重入直接 panic——把不可观测的 UB 换成可复现的 panic，这就是 `UPSafeCell` 的设计目标（书里那句“单核上安全的运行时借用检查能力”）。

所以它是**比 `RefCell` 更严**，不是更松。教材不是“忘了提供 `borrow`”，而是把共享借用这条路直接堵了。

## 两个常见坑

**坑一：`RefMut` 是守卫，drop 才释放。** 临时值通常语句结束就释放，但一旦 `let inner = ...` 绑定变量，它就活到作用域结束，期间任何重入都 panic。这就是 `run_next_task` 里必须手写 `drop(inner)` 才能调 `__switch` 的原因：

```rust
let mut inner = self.inner.exclusive_access();
// ...
drop(inner);                 // 不 drop，__switch 期间借用标记一直挂着
unsafe { __switch(current_task_cx_ptr, next_task_cx_ptr); }
```

如果换成共享借用，这个坑只会更多——因为 `&T` 看起来“无害”，最容易忘记 drop。

**坑二：`borrow_mut` 的 panic 不是 bug，是特性。** 你在 `exclusive_access()` 作用域内去调 `TASK_MANAGER.inner.exclusive_access()`，内核会直接 panic 在借用检查上，而不是悄悄破坏内存。调试这类 panic 时先找“谁借出去还没还”。

## main 分支的演进方向

`main` 分支里 `UPSafeCell` 已经被注释掉，换成了两个更严的东西（`os/src/sync/up.rs`）：

- `UPIntrFreeCell<T>`：`exclusive_access()` 在拿 `RefMut` 的同时**关中断**（可嵌套计数），drop 时恢复——语义从“借用检查”升级成“借用检查 + 关中断”，杜绝 trap 在借用窗口里插进来；
- `exclusive_session(|&mut T| -> V)`：闭包式 API，把借用生命周期压到最短，`&mut T` 不许逃逸；
- 另有一个裸的 `UPSafeCellRaw`（`UnsafeCell` + `get_mut()`），只给 `IntrMaskingInfo` 这种“必须绕过借用检查”的底层结构用。

方向很一致：**从来没有给过共享借用，只会越收越紧**。（再往后到第八章并发，就直接换成真正的 `Mutex`/`SpinLock` 了，语义从“单核运行时检查”变成“真互斥 + 可睡眠”。）

参考：[`os/src/sync/up.rs` (ch3-coop)](https://github.com/rcore-os/rCore-Tutorial-v3/blob/ch3-coop/os/src/sync/up.rs)、[`os/src/sync/up.rs` (main)](https://github.com/rcore-os/rCore-Tutorial-v3/blob/main/os/src/sync/up.rs)

