```rust
/// # Safety
/// - `addr` 非空，且按 `align_of::<T>()` 对齐
/// - `addr .. addr + size_of::<T>()` 是一块已初始化、合法的 `T`
/// - 读取期间没有 `&mut` 别名指向同一处
unsafe fn read_at<T: Copy>(addr: usize) -> T {
    (addr as *const T).read()
}

